// Package baseline reads and writes the baseline file, which lists the known issues of each check
// by their keys, see check.Issue.Key.
package baseline

import (
	"bytes"
	"fmt"
	"os"
	"sort"

	"gopkg.in/yaml.v3"
)

const header = `# Known CODEOWNERS issues, listed by check. They're reported but don't fail the validation.
# Remove an entry once its issue is fixed. Generated by "codeowners-validator baseline".
`

// Baseline maps the name of a check, as listed in CHECKS, to the keys of its known issues.
type Baseline map[string][]string

// Load reads the baseline file at path.
func Load(path string) (Baseline, error) {
	content, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("while reading the baseline: %w", err)
	}

	var b Baseline
	if err := yaml.Unmarshal(content, &b); err != nil {
		return nil, fmt.Errorf("while parsing the baseline %s: %w", path, err)
	}
	return b, nil
}

// Write writes the baseline to the file at path, with the keys of each check sorted and without
// duplicates.
func Write(path string, b Baseline) error {
	sorted := make(Baseline, len(b))
	for name, keys := range b {
		if len(keys) == 0 {
			continue
		}
		keys = append([]string(nil), keys...)
		sort.Strings(keys)
		unique := keys[:1]
		for _, k := range keys[1:] {
			if k != unique[len(unique)-1] {
				unique = append(unique, k)
			}
		}
		sorted[name] = unique
	}

	var buf bytes.Buffer
	buf.WriteString(header)
	if len(sorted) > 0 {
		enc := yaml.NewEncoder(&buf)
		enc.SetIndent(2)
		if err := enc.Encode(sorted); err != nil {
			return fmt.Errorf("while encoding the baseline: %w", err)
		}
		if err := enc.Close(); err != nil {
			return fmt.Errorf("while encoding the baseline: %w", err)
		}
	}

	if err := os.WriteFile(path, buf.Bytes(), 0o644); err != nil { //nolint:gosec // the baseline is committed with the repository
		return fmt.Errorf("while writing the baseline: %w", err)
	}
	return nil
}
